const fs = require('node:fs');

function read(path) { return fs.readFileSync(path, 'utf8'); }
function write(path, value) { fs.writeFileSync(path, value); }
function replaceOnce(path, oldValue, newValue) {
  const text = read(path);
  const count = text.split(oldValue).length - 1;
  if (count !== 1) throw new Error(`${path}: expected one replacement, found ${count}`);
  write(path, text.replace(oldValue, newValue));
}
function replaceSection(path, startMarker, endMarker, replacement) {
  const text = read(path);
  const start = text.indexOf(startMarker);
  const end = text.indexOf(endMarker, start + startMarker.length);
  if (start < 0 || end < 0) throw new Error(`${path}: section markers not found`);
  write(path, text.slice(0, start) + replacement + '\n\n' + text.slice(end));
}
function replaceToEnd(path, startMarker, replacement) {
  const text = read(path);
  const start = text.indexOf(startMarker);
  if (start < 0) throw new Error(`${path}: end-section marker not found`);
  write(path, text.slice(0, start) + replacement + '\n');
}

